from pathlib import Path
import json,sys,py_compile
b=Path('outputs/Шнек 1 — параметрическая модель').resolve();sys.path.insert(0,str(b));import journal
before=json.loads((b/'full_interference_audit_20261004_before.json').read_text(encoding='utf-8'));after=json.loads((b/'full_interference_audit_20261004_final.json').read_text(encoding='utf-8'));opening=json.loads((b/'open_verification_20261004.json').read_text(encoding='utf-8'));tests=json.loads((b/'parameter_roundtrip_20261004.json').read_text(encoding='utf-8'))
threshold=.001;old=[r for r in before['interferences'] if r['volume_mm3']>threshold];remaining=[r for r in after['interferences'] if r['volume_mm3']>threshold]
assert not remaining,remaining;assert opening['ok'] and not opening['partial'],opening
state=json.loads((b/'state.json').read_text(encoding='utf-8'));assert state['values']['pitch']==105 and state['values']['turns']==24
text=f"""# Исправление сборки и параметрических связей — 04.10.2026

## Результат проверки

- Рабочая сборка: 204 компонента; «Сбрасыватель» удалён, отверстие Ø110 мм сохранено по указанию пользователя.
- Потерянные файлы: {opening['missing_files']}.
- Подавленные компоненты: {opening['suppressed_components']}.
- Ошибки сопряжений: {opening['broken_mates']}.
- Другие ошибки элементов всех используемых документов: {opening['other_feature_errors']}.
- Объёмные пересечения более 0,001 мм³: {len(old)} до исправлений → {len(remaining)} после исправлений.
- SOLIDWORKS возвращает {after['count']} записей контактов; оставшиеся записи имеют нулевой или численно пренебрежимый объём ≤0,001 мм³. Они не скрыты из исходного протокола.

## Что исправлено

1. Восстановлены потерянные сопряжения и исключён неиспользуемый эскиз с оборванными внешними ссылками.
2. Исправлены корпуса и посадки верхней и нижней обойм, габаритные модели манжет 50×70×10, канавки и соосность стопорных колец. Нижняя канавка D40 дополнительно смещена на 0,25 мм по фактическому положению кольца.
3. Винт ограничен 24 витками. Нативная спираль и массив связаны с одним шагом; ранее спираль имела 100 мм при массиве 105 мм. Верхний торец связан с длиной винтовой части и толщиной лопасти. Удалено дублирующее вспомогательное тело.
4. Крепёжная окружность фланцев трубы приведена к Ø170 мм. Сварные уши и подкосы подрезаны по соседним деталям. С зеркального подкоса удалена повторная подрезка, уже не пересекающая тело; объём и положение сохранены.
5. Верхняя обойма получила сопряжение отверстий своего фланца и фланца трубы. Устранён свободный поворот приблизительно 0,242°, вызывавший несовпадение крепежа и шпонки.
6. В обеих импортированных прокладках выровнены центры отверстий по окружности Ø170 мм с угловым шагом 45°. Диаметр Ø8,8 мм, толщина и объём материала сохранены.
7. Для резьбовых соединений создано отдельное сборочное изображение; для каталожного привода объединены перекрывающиеся тела с сохранением внешней оболочки. Исходные конфигурации сохранены.
8. Программа параметров и программа чертежей подключены к фактическим рабочим ревизиям трубы, винта и опоры. Исправлена активация документов по полному пути через ActivateDoc3. Перед изменением проверяется активный документ.
9. Сохранение после явного перестроения включает связанные документы без повторного перестроения при сохранении. Сервер последовательно выполняет операции CAD и не завершает процесс изменения модели по таймеру во время перестроения.

## Проверка параметризации

Проверено на реальных файлах SOLIDWORKS через программный мост: шаг 105 → 100 → 105 мм. Нативный размер D4 спирали равен заданному шагу на обоих проверенных значениях; все рабочие подсборки и главная сборка перестроены и сохранены без ошибок элементов. Исходные параметры возвращены: 105 мм и 24 витка.

Число витков 26 при текущем шаге отклоняется до изменения CAD. Для геометрии этого винта действует ограничение: шаг × число витков + две толщины лопасти ≤ рабочая длина + 85 мм.

Это проверка указанных значений и текущей сборки; она не подтверждает все возможные сочетания параметров.

## Условия проверки геометрии

SOLIDWORKS InterferenceDetectionManager: подсборки раскрыты до отдельных деталей; внутренние пересечения многотельных деталей включены; скрытые тела проверены; совпадающие поверхности не считаются пересечением. Порог учёта объёма — 0,001 мм³.

Использована конфигурация «Сборочная — резьба условно» для гаек М6/М8/М10, отверстий М8 привода и М12 верхнего вала, а также концевых зон кранов G1/2. Условный просвет исключает столкновение гладкого цилиндра метиза с упрощённым внутренним диаметром резьбы. Он **не является диаметром сверления или геометрией реального профиля резьбы**. Центральный проход и положение кранов сохранены. Входные кромки условных зон уточнены до внешнего контура скруглённого корпуса.

Нулевая проверка объёмных пересечений относится к этому сборочному представлению. Она не подтверждает профили изготовленной резьбы, рабочую кромку манжеты, прочность, герметичность или технологические допуски. Исходные конфигурации и резервные копии сохранены; сведения об изменениях внесены в журнал проекта.

## Протоколы

- full_interference_audit_20261004_before.json — исходные пересечения.
- full_interference_audit_20261004_final.json — все записи итоговой проверки без фильтрации.
- open_verification_20261004.json — проверка фактической команды открытия сборки.
- parameter_roundtrip_20261004.json — проверка изменения шага и отказа от 26 витков.
- mate_diagnostics_20261004.json — сопряжения сборочных документов.
- recovered_assembly_check.json — используемые файлы и пути.
- journal.json — журнал изменений проекта.
"""
(b/'Исправление сборки 04.10.2026.md').write_text(text,encoding='utf-8')
if not any(e.get('repair_id')=='final-cad-check-20261004' for e in journal._read()['entries']):journal._append({'type':'model_change','repair_id':'final-cad-check-20261004','title':'Итоговая проверка сборки и изменения шага','change_count':3,'changes':[{'key':'valve_rim','name':'Входные кромки условных зон G1/2','before':'Два пересечения около 5.8 мм³ у входной кромки','after':'Уточнена только сборочная геометрия входа; центральный проход и глубина посадки сохранены'},{'key':'verification','name':'Проверка всей сборки','before':f'{len(old)} объёмных областей более 0.001 мм³','after':'0 объёмных областей более 0.001 мм³; 0 ошибок сопряжений и элементов; 0 потерянных файлов'},{'key':'parameter_test','name':'Программная параметризация','before':'Связь нативной спирали и вызова программы требовала проверки','after':'Шаг 100 и 105 мм проверен по D4 реальной спирали; 26 витков отклонены; параметры восстановлены'}]})
